import{z as n,x as A,o as r,c as p,q as i,j as B,D as e,d as s,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"DiffServ","description":"","frontmatter":{"title":"DiffServ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/diffserv-qos.md","filePath":"cs/diffserv-qos.md","lastUpdated":1791413859000}'),d={name:"cs/diffserv-qos.md"};function f(D,a,F,S,P,C){const t=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="diffserv" tabindex="-1">DiffServ <a class="header-anchor" href="#diffserv" aria-label="Permalink to &quot;DiffServ&quot;">​</a></h1><div class="epigraph"><p>DSCP 把包分到少量行为聚集，每跳 PHB（EF/AF/BE）执行；可扩展，但不在互联网上承诺端到端预留。</p><footer>—— 据 RFC 2474 / 2475 DiffServ；RFC 3246 EF；RFC 2597 AF 整理</footer></div><p><a href="/cs/wfq-fair-queue">WFQ</a> 每流不扩展。<a href="/cs/token-bucket-shaping">令牌桶</a> 可按类。<a href="/cs/token-bucket-shaping">上一课</a> 留下着色。缺口是 <strong>DiffServ 架构</strong>：标记、PHB、边界信任。本课不把 TSO 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IntServ/RSVP 每流预留在核心炸状态。DiffServ：边缘分类打 DSCP，核心只看 6 比特做 EF（低延迟）、AF（分档丢弃）、BE。无端到端硬合同，除非域内 SLA。与 5G 切片对照：切片是硬隔离实例，DSCP 是软着色。PFC 用 802.1p，要在边缘映射到 DSCP。</p><p><span class="marginnote">术语翻译：PHB（每跳行为）就是「每一台路由器对这类包承诺怎么对待」——先发给谁、拥塞时先丢谁。它只约束单台路由器的本地行为，像酒店每层各自的服务标准，拼起来并不自动等于一条端到端保证。</span></p><p>不要把 EF 写成 URLLC 保证：没有资源预留则 EF 也会挤。</p><p><span class="marginnote">RFC 2475 框架。核心「简」是可扩展理由。本课不把 64 个码点背完。</span></p><h3 id="域内着色" tabindex="-1">域内着色 <a class="header-anchor" href="#域内着色" aria-label="Permalink to &quot;域内着色&quot;">​</a></h3><p>少量 PHB 可扩展，无全球预留。IXP 常重标记。EF 无资源也会挤。主机乱打 EF 会被边缘改写。</p><p><span class="marginnote">直觉类比：EF 是救护车道——延迟最低，但要交警（资源规划）配合，车一多照样堵；AF 是分舱位的民航——票分三档，超售时先请低舱位改签；BE 是候机大厅——人人可坐，拥塞时排队最没怨言权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：边缘分类+桶 → DSCP → 核心 PHB。对照 EVPN/QoS：租户类在覆盖内外要映射。IXP 通常不信你的 DSCP，会重置。</p>',13)),(r(),B(l,null,{default:e(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E8%BE%B9%E7%BC%98%E5%88%86%E7%B1%BB%E6%95%B4%E5%BD%A2%22%5D%20--%3E%20DS%5B%22DSCP%22%5D%0A%20%20DS%20--%3E%20PHB%5B%22%E6%AF%8F%E8%B7%B3%20EF%2FAF%2FBE%22%5D%0A%20%20UNTRUST%5B%22%E4%B8%8D%E4%BF%A1%E4%BB%BB%E5%9F%9F%22%5D%20--%3E%20RE%5B%22%E9%87%8D%E6%A0%87%E8%AE%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"AQM 可按 AF 颜色丢。ECN 与 DSCP 正交（ECN 用 TOS 低 2 位历史纠缠，实现要小心）。BGP 不传 DSCP 政策。RoCE 依赖边缘信任的优先级，跨域失效。",-1)),a[5]||(a[5]=E("p",null,"上面那张图画「包从边缘到核心的架构流向」；这张回答更细的问题：同一个 AF 类里，绿黄红三档在拥塞时究竟谁先被丢。",-1)),(r(),B(l,null,{default:e(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22AF%20%E7%B1%BB%E7%9A%84%E5%8C%85%E8%BF%9B%E5%85%A5%E9%98%9F%E5%88%97%22%5D%20--%3E%20CLR%5B%22%E8%BE%B9%E7%BC%98%E6%8C%89%E6%89%BF%E8%AF%BA%E9%80%9F%E7%8E%87%E6%A0%87%E8%89%B2%20%E7%BB%BF%E9%BB%84%E7%BA%A2%22%5D%0A%20%20CLR%20--%3E%20Q%7B%22%E7%8E%B0%E5%9C%A8%E6%8B%A5%E5%A1%9E%E5%90%97%22%7D%0A%20%20Q%20--%20%22%E6%B2%A1%E6%8B%A5%E5%A1%9E%22%20--%3E%20FWD%5B%22%E5%85%A8%E9%83%A8%E6%AD%A3%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20Q%20--%20%22%E6%8B%A5%E5%A1%9E%22%20--%3E%20DROP%5B%22AQM%20%E6%8C%89%E4%B8%A2%E5%BC%83%E4%BC%98%E5%85%88%E7%BA%A7%E9%80%89%E4%B8%A2%22%5D%0A%20%20DROP%20--%3E%20R1%5B%22%E5%85%88%E4%B8%A2%20%E7%BA%A2%20%E8%B6%85%E9%80%9F%E6%9C%80%E5%A4%9A%E7%9A%84%22%5D%0A%20%20DROP%20--%3E%20R2%5B%22%E5%85%B6%E6%AC%A1%E4%B8%A2%20%E9%BB%84%22%5D%0A%20%20DROP%20--%3E%20R3%5B%22%E6%9C%80%E5%90%8E%E6%89%8D%E4%B8%A2%20%E7%BB%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：DSCP 是 IP 头旧 TOS 字段的前 6 比特，共 64 个码点。常用如 EF=46（二进制 101110）；AF 分四类、每类三个丢弃档；默认 0 就是普通尽力而为。所谓「打标」只是改 6 个比特，核心路由器查表执行，不必记任何一条流。</span></p><p>与 Saltzer：DiffServ 是性能，不是正确性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RSVP-TE 与 DiffServ-TE 的全部。TSO/LRO 是下一课。后课默认：公网尽力而为；DSCP 在单一信任域内有意义。</p><p>主机随意打 EF 会被边缘改写。</p><p>下一课<a href="/cs/tso-lro">TSO / LRO</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>少量 PHB 换可扩展 QoS。</li><li>合同在域边界，不在全球。</li><li>与切片、PFC 映射但不等价。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2474/2475；RFC 3246。</li></ul>',8))])}const m=n(d,[["render",f]]);export{c as __pageData,m as default};
